package io.github.chronicle.core.encounters;

import com.google.gson.*;
import com.google.gson.stream.*;
import java.io.*;
import java.nio.*;
import java.nio.channels.FileChannel;
import java.nio.charset.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;

/** Strict, bounded, atomically replaced configuration for portable encounter definitions. */
public final class EncounterGroupStore {
    public static final int SCHEMA_VERSION = 1; public static final long MAX_FILE_BYTES = 256 * 1024; private static final int MAX_DEPTH = 16;
    private final Path file; private final EncounterTypeAllowlist allowlist; private byte[] observed;
    public EncounterGroupStore(Path file, EncounterTypeAllowlist allowlist) { if (file == null || file.getFileName() == null) throw new IllegalArgumentException("encounter group file is required"); this.file = file.toAbsolutePath().normalize(); this.allowlist = Objects.requireNonNull(allowlist, "encounter type allowlist is required"); }
    public synchronized EncounterGroupRegistry loadOrCreate(EncounterGroupRegistry defaults) throws IOException {
        validate(defaults); verifyDirectories(file.getParent()); if (!Files.exists(file, LinkOption.NOFOLLOW_LINKS)) { byte[] initial = encode(defaults).getBytes(StandardCharsets.UTF_8); writeInitial(initial); observed = initial; return defaults; }
        byte[] bytes = current(); try { EncounterGroupRegistry configured = decode(bytes); TreeMap<String, EncounterGroup> merged = new TreeMap<>(defaults.groups()); merged.putAll(configured.groups()); if (merged.size() > EncounterGroupRegistry.MAX_GROUPS) throw new IllegalArgumentException("merged encounter groups exceed limit"); EncounterGroupRegistry result = new EncounterGroupRegistry(configured.revision(), merged); validate(result); observed = bytes.clone(); return result; } catch (RuntimeException failure) { throw new IOException("encounter group config is invalid and was not replaced: " + file + " (" + failure.getMessage() + ")", failure); }
    }
    public synchronized EncounterGroupRegistry replace(EncounterGroupRegistry observedRegistry, EncounterGroup replacement, EncounterGroup expected) throws IOException {
        if (observed == null) throw new IllegalStateException("encounter group configuration must be loaded before editing"); EncounterGroupRegistry next = observedRegistry.replace(replacement, expected); validate(next); byte[] old = current(); if (!MessageDigest.isEqual(observed, old)) throw new IOException("encounter group config changed outside Chronicle; reload before retrying"); try { decode(old); } catch (RuntimeException failure) { throw new IOException("encounter group config is invalid and was not replaced: " + file, failure); }
        byte[] encoded = encode(next).getBytes(StandardCharsets.UTF_8); if (encoded.length > MAX_FILE_BYTES) throw new IOException("encounter group serialization exceeds 256 KiB limit"); replaceDurably(old, encoded); observed = encoded.clone(); return next;
    }
    public synchronized EncounterGroupRegistry remove(EncounterGroupRegistry observedRegistry, String id, EncounterGroup expected) throws IOException {
        if (observed == null) throw new IllegalStateException("encounter group configuration must be loaded before editing"); EncounterGroupRegistry next = observedRegistry.remove(id, expected); byte[] old = current(); if (!MessageDigest.isEqual(observed, old)) throw new IOException("encounter group config changed outside Chronicle; reload before retrying"); try { decode(old); } catch (RuntimeException failure) { throw new IOException("encounter group config is invalid and was not replaced: " + file, failure); }
        byte[] encoded = encode(next).getBytes(StandardCharsets.UTF_8); replaceDurably(old, encoded); observed = encoded.clone(); return next;
    }
    public static String encode(EncounterGroupRegistry registry) { Objects.requireNonNull(registry, "encounter registry is required"); JsonObject root = new JsonObject(); root.addProperty("schemaVersion", SCHEMA_VERSION); root.addProperty("revision", registry.revision()); JsonArray groups = new JsonArray(); for (EncounterGroup group : registry.groups().values()) { JsonObject value = new JsonObject(); value.addProperty("id", group.id()); value.addProperty("label", group.label()); value.addProperty("description", group.description()); JsonArray members = new JsonArray(); for (EncounterMember member : group.members()) { JsonObject m = new JsonObject(); m.addProperty("entityType", member.entityType()); m.addProperty("count", member.count()); members.add(m); } value.add("members", members); groups.add(value); } root.add("groups", groups); return root.toString(); }
    public static EncounterGroupRegistry decode(String json) { return decode(json.getBytes(StandardCharsets.UTF_8)); }
    private static EncounterGroupRegistry decode(byte[] bytes) { String json = utf8(bytes); JsonElement parsed; try (JsonReader reader = new JsonReader(new StringReader(json))) { reader.setStrictness(Strictness.STRICT); strict(reader, 0); if (reader.peek() != JsonToken.END_DOCUMENT) throw new IllegalArgumentException("encounter JSON has trailing content"); } catch (IOException e) { throw new IllegalArgumentException("unable to read encounter JSON", e); } try (JsonReader reader = new JsonReader(new StringReader(json))) { reader.setStrictness(Strictness.STRICT); parsed = JsonParser.parseReader(reader); } catch (IOException e) { throw new IllegalArgumentException("unable to parse encounter JSON", e); }
        JsonObject root = object(parsed, "root"); fields(root, Set.of("schemaVersion", "revision", "groups"), "root"); if (integer(required(root,"schemaVersion"), "schemaVersion") != SCHEMA_VERSION) throw new IllegalArgumentException("unsupported encounter schemaVersion"); JsonArray groups = array(required(root,"groups"), "groups"); if (groups.size() > EncounterGroupRegistry.MAX_GROUPS) throw new IllegalArgumentException("too many encounter groups"); Map<String, EncounterGroup> values = new LinkedHashMap<>(); for (int i=0;i<groups.size();i++) { JsonObject g=object(groups.get(i),"groups["+i+"]"); fields(g,Set.of("id","label","description","members"),"group"); JsonArray members=array(required(g,"members"),"members"); List<EncounterMember> list=new ArrayList<>(); for (JsonElement value:members) { JsonObject m=object(value,"member"); fields(m,Set.of("entityType","count"),"member"); list.add(new EncounterMember(string(required(m,"entityType"),"entityType"),integer(required(m,"count"),"count"))); } EncounterGroup group=new EncounterGroup(string(required(g,"id"),"id"),string(required(g,"label"),"label"),string(required(g,"description"),"description"),list); if(values.putIfAbsent(group.id(),group)!=null)throw new IllegalArgumentException("duplicate encounter group ID"); } return new EncounterGroupRegistry(longNumber(required(root,"revision"),"revision"),values);
    }
    private void validate(EncounterGroupRegistry registry) { for (EncounterGroup group : registry.groups().values()) group.requireAllowed(allowlist); }
    private byte[] current() throws IOException { verifyDirectories(file.getParent()); if (Files.isSymbolicLink(file) || !Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)) throw new IOException("encounter group path is not a regular non-link file: " + file); if (Files.size(file)>MAX_FILE_BYTES) throw new IOException("encounter group config exceeds 256 KiB limit"); return Files.readAllBytes(file); }
    private void writeInitial(byte[] bytes) throws IOException { prepare(file.getParent()); Path temp=Files.createTempFile(file.getParent(),file.getFileName().toString(),".tmp"); try { force(temp,bytes); try { Files.createLink(file,temp); } catch(FileAlreadyExistsException e) { throw new IOException("encounter group config appeared while creating it",e); } } finally { Files.deleteIfExists(temp); } }
    private void replaceDurably(byte[] old, byte[] encoded) throws IOException { prepare(file.getParent()); Path temp=Files.createTempFile(file.getParent(),file.getFileName().toString(),".tmp"), backupTemp=null; try { force(temp,encoded); verify(old); Path backup=file.resolveSibling(file.getFileName()+".bak"); if(Files.exists(backup,LinkOption.NOFOLLOW_LINKS)&&(Files.isSymbolicLink(backup)||!Files.isRegularFile(backup,LinkOption.NOFOLLOW_LINKS)))throw new IOException("encounter group backup is not a regular non-link file"); backupTemp=Files.createTempFile(file.getParent(),backup.getFileName().toString(),".tmp"); force(backupTemp,old); move(backupTemp,backup); backupTemp=null; verify(old); move(temp,file); } finally { Files.deleteIfExists(temp); if(backupTemp!=null) Files.deleteIfExists(backupTemp); } }
    private void verify(byte[] expected) throws IOException { if(!MessageDigest.isEqual(expected,current())) throw new IOException("encounter group config changed outside Chronicle during save; reload before retrying"); }
    private static void verifyDirectories(Path directory)throws IOException { Path absolute=directory.toAbsolutePath().normalize(),cursor=absolute.getRoot();if(cursor==null)throw new IOException("encounter group path has no filesystem root");for(Path part:absolute){cursor=cursor.resolve(part);if(Files.exists(cursor,LinkOption.NOFOLLOW_LINKS)&&(Files.isSymbolicLink(cursor)||!Files.isDirectory(cursor,LinkOption.NOFOLLOW_LINKS)))throw new IOException("encounter group directory is a symbolic link or special file: "+cursor);}}
    private static void prepare(Path directory)throws IOException { verifyDirectories(directory); if(!Files.exists(directory,LinkOption.NOFOLLOW_LINKS))Files.createDirectories(directory); verifyDirectories(directory); }
    private static void force(Path p,byte[] b)throws IOException { try(FileChannel c=FileChannel.open(p,StandardOpenOption.WRITE,StandardOpenOption.TRUNCATE_EXISTING)){ByteBuffer x=ByteBuffer.wrap(b);while(x.hasRemaining())c.write(x);c.force(true);} }
    private static void move(Path a,Path b)throws IOException { try{Files.move(a,b,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){throw new IOException("atomic replacement is not supported for encounter group config",e);} }
    private static String utf8(byte[] bytes) { try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();}catch(CharacterCodingException e){throw new IllegalArgumentException("encounter JSON is not valid UTF-8",e);} }
    private static void strict(JsonReader r,int depth)throws IOException { if(depth>MAX_DEPTH)throw new IllegalArgumentException("encounter JSON nesting exceeds "+MAX_DEPTH); switch(r.peek()){case BEGIN_OBJECT->{r.beginObject();Set<String>s=new HashSet<>();while(r.hasNext()){String n=r.nextName();if(!s.add(n))throw new IllegalArgumentException("duplicate JSON member: "+n);strict(r,depth+1);}r.endObject();}case BEGIN_ARRAY->{r.beginArray();while(r.hasNext())strict(r,depth+1);r.endArray();}case STRING,NUMBER->r.nextString();case BOOLEAN->r.nextBoolean();case NULL->r.nextNull();default->throw new IllegalArgumentException("unexpected encounter JSON token");} }
    private static JsonObject object(JsonElement e,String n){if(e==null||!e.isJsonObject())throw new IllegalArgumentException(n+" must be an object");return e.getAsJsonObject();} private static JsonArray array(JsonElement e,String n){if(e==null||!e.isJsonArray())throw new IllegalArgumentException(n+" must be an array");return e.getAsJsonArray();} private static JsonElement required(JsonObject o,String n){if(!o.has(n)||o.get(n).isJsonNull())throw new IllegalArgumentException("missing "+n);return o.get(n);} private static void fields(JsonObject o,Set<String>a,String n){if(!o.keySet().equals(a))throw new IllegalArgumentException(n+" fields do not match schema");} private static String string(JsonElement e,String n){if(!e.isJsonPrimitive()||!e.getAsJsonPrimitive().isString())throw new IllegalArgumentException(n+" must be a string");return e.getAsString();} private static int integer(JsonElement e,String n){long x=longNumber(e,n);if(x<Integer.MIN_VALUE||x>Integer.MAX_VALUE)throw new IllegalArgumentException(n+" outside integer range");return(int)x;} private static long longNumber(JsonElement e,String n){if(!e.isJsonPrimitive()||!e.getAsJsonPrimitive().isNumber()||!e.getAsString().matches("-?(0|[1-9][0-9]*)"))throw new IllegalArgumentException(n+" must be an integer");try{return Long.parseLong(e.getAsString());}catch(NumberFormatException x){throw new IllegalArgumentException(n+" outside long range",x);}}
}
